        Console.WriteLine("UInt64<-UInt64 " + Util.Row<UInt64, UInt64>(new UInt64[] { UInt64.MinValue, (UInt64)1, (UInt64)100, (UInt64)127, (UInt64)128, (UInt64)255, (UInt64)256, (UInt64)32767, (UInt64)32768, (UInt64)65535, (UInt64)65536, (UInt64)2147483647, (UInt64)2147483648, (UInt64)4294967295, (UInt64)4294967296, (UInt64)9223372036854775807, UInt64.MaxValue }));
    }
